INSERT INTO `announcement` VALUES (5,'网站公告','<p>✅ 平台提供以下核心服务：</p><ul><li>商品管理：类目维护、SKU管理、多仓库存同步</li><li>订单协同：订单自动分发、状态追踪、异常预警</li><li>供应链金融：账期管理、对账结算、电子发票</li><li>物流对接：主流快递/仓储系统API直连、运单智能匹配</li><li>数据分析：经营报表、库存周转、履约时效可视化</li><li>权限管理：多角色账号体系、操作日志审计</li></ul><p>❌ 以下情形不属于平台服务保障范围：</p><ul><li>用户未按操作规范导致的业务异常</li><li>第三方系统（如快递、支付、ERP）故障引发的链路中断</li><li>因用户网络环境、设备兼容性问题造成的访问异常</li><li>不可抗力（如自然灾害、政策调整、黑客攻击）导致的服务暂停</li></ul>','2026-05-04 11:19:34','2026-05-26 03:39:04'),(6,'网站介绍','<p><span style=\"color: rgb(140, 141, 155);\">供应链端电商管理平台是一款专为电商企业、品牌商家及供应链服务商打造的一站式智能协同系统。</span></p><p><span style=\"color: rgb(140, 141, 155);\">通过「订单+库存+物流+财务」全链路数字化整合，帮助客户实现供应链可视、可控、可优化，降本增效，敏捷响应市场变化</span></p><h2>﻿适用客户群体</h2><p>✅ 电商品牌方：多平台开店、多仓发货，需统一管控供应链</p><p>✅ 代运营/TP服务商：为多个品牌提供供应链托管服务</p><p>✅ 批发分销商：上下游协同复杂，需高效订单流转与对账</p><p>✅ 跨境卖家：涉及海外仓、报关、多币种结算等复杂场景</p><p>✅ 制造业转型电商：从生产到零售的端到端供应链数字化</p>','2026-05-04 11:23:58','2026-05-26 03:38:59'),(7,'关于我们','<h2>公司简介</h2><p>供应链端电商管理平台（Xiaozhi Supply Chain Platform）成立于<span style=\"color: rgb(97, 92, 237); background-color: rgb(239, 238, 255);\">202X年</span>，是一家专注于电商供应链数字化服务的高新技术企业。</p><p>我们立足<span style=\"color: rgb(97, 92, 237); background-color: rgb(239, 238, 255);\">[城市/总部所在地]</span>，服务辐射全国及东南亚、欧美等跨境市场，致力于为电商品牌、零售企业、供应链服务商提供端到端的智能协同解决方案。</p><ul><li><br></li></ul>','2026-05-04 11:26:00','2026-05-26 03:38:35'),(8,'联系方式','<p>系统使用/技术故障</p><p>客服热线 / 工单系统</p><p>400-xxx-xxxx</p><p>按2转技术支持</p><p>工作日 9:00-18:00</p>','2026-05-04 11:28:40','2026-05-26 03:39:07');
/*!40000 ALTER TABLE `announcement` ENABLE KEYS */;
UNLOCK TABLES;

