INSERT INTO `commodity_information` VALUES (21,'1777695462707','优选甘草橄榄','零食/蜜饯果干','秋林','100ml/罐装',18.00,'/api/upload/O1CN01EBbQPP1q2CWxm7wtb_!!4611686018427385277-0-item_pic.jpg_460x460q90.jpg_.webp',4.00,'这是一款传统风味的甘草橄榄零食，软糯香甜的口感深受大众喜爱。100ml的罐装设计既方便携带又保鲜效果好。无论是自己享用还是馈赠亲友，都是不错的选择。\n','<p><img src=\"data:image/png;base64,\"></p>',45,4,0,0,0,0,0,'2026-05-02 12:18:57','2026-05-24 11:36:59',1,0),(23,'1777879472353','明光袜子','衣物','明光','均码/多色可选',19.00,'/api/upload/O1CN01A1wr3R26fA5Ne05Sj_!!2219275407688.png_460x460q90.jpg_.webp',3.00,'明光袜子是一款经济实惠、舒适耐穿的日常袜品，专为追求性价比的消费者设计。采用优质棉混纺面料制作，具有良好的吸汗透气性能，适合四季穿着。无论是日常通勤、运动休闲还是居家生活，明光袜子都能为您提供舒适的穿着体验。\n','<p><img src=\"data:image/png;base64,\"></p>',14,2,1,3,2,0,0,'2026-05-04 15:25:21','2026-05-27 01:37:54',0,0),(24,'1777778101568','得力中性笔','办公用品','得力','0.5mm/黑色/12支装',71.00,'/api/upload/ad8316f0-e979-46c6-b8bf-7a29b59f36af.png',10.00,'得力（deli）是中国知名文具品牌，专注于办公用品和文具产品的研发、生产和销售。得力中性笔以其性价比高、书写流畅、品质可靠而深受消费者喜爱\n','<p><img src=\"data:image/png;base64,\"></p>',6,2,2,0,0,0,0,'2026-05-05 01:37:59','2026-05-26 16:49:35',0,0),(25,'1778211129401','wvwe','','ww','vww',1.00,'',1.00,'','',0,0,0,0,0,0,0,'2026-05-08 11:32:26','2026-05-08 03:51:39',1,0),(26,'1778211174945','','','','',0.00,'',0.00,'','',0,0,0,0,0,0,0,'2026-05-08 11:33:04','2026-05-08 03:51:39',1,0),(27,'1778211231256','','','','',0.00,'',0.00,'','',0,0,0,0,0,0,0,'2026-05-08 11:46:44','2026-05-08 03:51:39',1,0),(28,'1778212172640','听听手表','手表','听听','标准版/黑色表盘/硅胶表带',10.00,'/api/upload/1777884065.png',12.00,'听听手表是一款性价比超高的实用腕表，简约时尚的设计，适合日常佩戴。无论是学生上课、上班族通勤，还是运动健身，都能满足您的时间管理需求。\n','<p><span class=\"ql-cursor\">﻿</span><img src=\"data:image/png;base64,\"></p>',1,1,0,0,0,0,0,'2026-05-08 11:49:34','2026-05-24 03:38:36',0,0),(29,'1778214303088','旺仔馒头','零食','旺仔','100g',16.00,'/api/upload/1779092907.png',1.00,'旺仔小馒头，源自旺旺集团经典食品研发体系，精选优质大米粉与脱脂奶粉，采用微孔膨化+低温烘焙工艺，打造“咬下咔滋响、入口即融化”的独特口感。每颗小馒头表面均匀附着细砂糖霜与奶香涂层，大小适中、圆润可爱，专为儿童及家庭休闲场景设计。自上市以来，凭借稳定的品控与亲民定价，常年位居超市零食货架畅销榜，是无数人童年抽屉里的“白色宝藏”。\n','<p><img src=\"data:image/png;base64,\"></p>',12,1,0,0,0,0,0,'2026-05-08 12:25:30','2026-05-26 11:04:27',0,0),(31,'1779623569390','旺旺水','水','旺旺','200ml',9.00,'/api/upload/1779622467.png',2.00,'','',0,0,0,0,0,0,0,'2026-05-24 19:53:23','2026-05-24 11:55:31',1,0),(32,'1779623762634','旺旺水','水','旺旺','200ml',49.00,'/api/upload/1779622467.png',2.00,'','',1,0,0,0,0,0,0,'2026-05-24 19:56:31','2026-05-27 01:38:09',0,0);
