--
-- Table structure for table `supply_information`
--

DROP TABLE IF EXISTS `supply_information`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supply_information` (
  `supply_infor_id` int NOT NULL AUTO_INCREMENT COMMENT '主键，供应标识',
  `supplier_na` varchar(64) NOT NULL COMMENT '供应商名称',
  `suppliers_phone_number` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '供应商电话',
  `comm_category` varchar(64) NOT NULL COMMENT '商品类别',
  `compreh_eva` varchar(64) DEFAULT NULL COMMENT '综合评价',
  `supply_freq` varchar(64) NOT NULL COMMENT '供应频率',
  `supply_products` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '供应产品',
  `product_quality` text COMMENT '产品质量',
  `cooperation_situ` text COMMENT '合作情况',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否删除：0未删除，1已删除',
  PRIMARY KEY (`supply_infor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应信息';
/*!40101 SET character_set_client = @saved_cs_client */;

