INSERT INTO `supply_information` VALUES (15,'好又多','13658528542','办公用品','好评','每周2次','常规办公文具及耗材：\n书写工具：中性笔（黑/红/蓝）、圆珠笔、记号笔、荧光笔。\n纸张本册：A4/A3复印纸、B5软面抄、便利贴、档案袋。\n桌面工具：剪刀、美工刀、订书机、订书钉、回形针、长尾夹、胶带、修正带。\n文件收纳：档案盒、文件夹（单/双夹）、文件袋、名片册。','准入筛选：主要代理市面知名品牌（如得力、晨光等）及优质白牌产品，拒绝“三无”劣质文具。\n验收标准：实行入库抽检，重点测试中性笔出水流畅度（不断墨、不漏墨）及纸张平整度（不卡纸）。\n售后保障：建立快速退换机制，对于书写不畅、配件损坏等质量问题，支持7天内无条件退换，保障办公效率。','履约情况：配合度极高，能严格准时执行“每周2次”的补货计划，从未出现断货影响办公的情况。\n服务响应：对于突发需求（如大型会议急需文具），能配合进行紧急加急配送。\n成本优势：作为批发型供应商，价格透明且极具竞争力，有效降低了公司的日常办公采购成本。\n综合建议：合作期间无纠纷，信誉良好，建议作为核心供应商续签年度供货协议。','2026-05-02 12:20:06','2026-05-26 16:02:08',1),(16,'明平','13141313141','衣物','好评','每周5次','1. 各类袜子（棉袜、运动袜、商务袜等）\n2. 内衣内裤系列\n3. 家居服/睡衣套装\n4. 围巾、手套等配饰\n5. 其他针织类衣物产品','• 采用优质棉料及混纺面料，符合国家纺织品质量标准\n• 拥有完善的质量检测体系，每批次产品均经过严格检验\n• 面料柔软舒适，透气吸汗性能良好\n• 缝制工艺精细，走线平整，不易开线变形\n• 通过ISO9001质量管理体系认证\n• 产品合格率保持在98%以上','合作亮点：\n- 供货稳定，每周5次供应频率能满足需求\n- 产品质量可靠，客户投诉率低\n- 价格实惠，性价比高\n- 配合度高，能及时响应订单需求\n- 包装规范，物流配送及时\n\n注意事项：\n- 建议提前3天下单以确保供应\n- 季节性产品需提前备货\n- 定期沟通新品开发方向','2026-05-08 11:33:27','2026-05-18 09:21:53',0),(17,'旺仔','13145323252','零食','好评较多','每周3次','1. 旺仔牛奶系列（原味、高钙、巧克力奶等）\n2. 糖果果冻系列（旺仔QQ糖、O泡果奶等）\n3. 膨化食品系列（旺旺仙贝、旺旺雪饼）\n4. 饼干系列（旺仔小馒头、黑白配夹心饼干）\n5. 其他休闲食品','✅ 品牌背景：旺旺集团旗下，拥有完善的供应链体系[[11]][[12]]\n✅ 原料控制：采用进口乳源，从乳源检验到灌装全程无菌监控[[13]]\n✅ 生产管理：拥有先进的生产设备和严格的质量检测体系\n✅ 产品认证：通过国家食品安全认证，符合行业标准\n✅ 市场表现：产品在全国零食量贩店、商超广泛销售，市场认可度高[[7]][[8]]\n✅ 售后服务：完善的客服体系，及时处理客户反馈','亮点：\n• 品牌知名度高，消费者认可度强\n• 产品质量稳定，投诉率低\n• 供货及时，配送体系完善\n• 产品线丰富，满足不同渠道需求\n• 在零食量贩店表现突出，销量稳定增长[[9]]\n\n注意事项：\n• 建议保持合理库存，确保供应连续性\n• 关注新品上市动态，及时调整采购计划\n• 定期沟通促销活动，提升销售业绩','2026-05-08 12:19:00','2026-05-18 09:18:16',0),(18,'卡椒','18523527801','手表','好评','一周一次','时尚腕表：简约休闲手表、复古风手表、情侣对表。\n功能手表：电子学生表、运动电子表、防水石英表。\n智能穿戴：基础款智能手环、蓝牙通话手表。\n配件类：通用表带、表盒包装。','精准度检测：所有入库手表均经过走时测试，确保日误差在标准范围内（±30秒/天）。\n外观质检：严格检查表镜是否无划痕、表壳无毛刺、表带缝合紧密，杜绝次品。\n防水测试：针对生活防水款进行喷淋测试，确保日常洗手防溅水功能有效。\n包装防护：采用加厚气泡袋+硬盒包装，有效降低长途运输导致的损坏率。','履约稳定：严格遵守“一周一次”的供货周期，从无怨言或推迟，补货节奏把控很好。\n款式优势：新品更新速度快，经常能提供当下流行的款式，有助于提升店铺吸引力。\n售后配合：遇到个别电池没电或表带松动的客诉，能迅速配合退换，服务态度良好。\n建议：继续保持目前的供货节奏，建议在换季（如夏季防水表、冬季金属表）前适当增加单次备货量。','2026-05-18 17:26:57','2026-05-18 09:26:57',0);
/*!40000 ALTER TABLE `supply_information` ENABLE KEYS */;
UNLOCK TABLES;

